local player = game:GetService("Players").LocalPlayer; 
local nearestPlayer = nil; 
local distance = math.huge; 
for _, v in pairs(game:GetService("Players"):GetPlayers()) do 
    if v ~= player then 
        local dist = (v.Character or v.CharacterAdded:Wait()).PrimaryPart.Position - player.Character.PrimaryPart.Position; 
        if dist.magnitude < distance then 
            nearestPlayer = v; 
            distance = dist.magnitude; 
        end 
    end 
end 
return nearestPlayer; 
//End of function 
//Main code 
